-- 事故评论（2026-11-22，ADR-0034；契约 plans/incident-collaboration-accept.md）。
-- 设计约束：
--   ① 评论是对话事实，append-only：服务端只 INSERT，不提供编辑/删除，也不由客户端整段覆盖；
--      这与 incidents.timeline_json 的「状态快照」语义刻意分开（后者多人同时补记录会后写赢）。
--   ② 所有查询仍带 tenant 条件，tenant 只来自 JWT；跨租户读一律 404。
--   ③ mentions_json 存服务端从正文解析出的用户数组（JSON），客户端传的数组只作提示。
--   ④ 评论不进入检索 / LLM / 指纹 / 缓存键，只是给人看的协作记录。
-- 自增主键写 IDENTITY 而不是 AUTO_INCREMENT：H2 的 PostgreSQL 兼容模式（测试库）不认
-- AUTO_INCREMENT，而 GENERATED BY DEFAULT AS IDENTITY 在 H2 两种模式与 PostgreSQL 10+ 都成立。
CREATE TABLE IF NOT EXISTS incident_comments (
    comment_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant        VARCHAR(64)   NOT NULL,
    incident_id   VARCHAR(64)   NOT NULL,
    author        VARCHAR(64)   NOT NULL,
    -- 正文上限是 2000 个 code point（服务端口径）；2000 个表情最坏是 4000 个 UTF-16 码元。
    -- 列宽按码元数取 4000：H2 按 UTF-16 码元计量、PostgreSQL 按字符计量，两边都装得下。
    body          VARCHAR(4000) NOT NULL,
    mentions_json CLOB,
    created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_incident_comments_tenant_incident_at
    ON incident_comments(tenant, incident_id, created_at);
